// Préparer les paramètres de recherche
const query = $input.first().json.query || {};

const params = {
  limit: query.limit || 50,
  status: query.status || null,
  after: query.after || null,
  before: query.before || null,
  customer_id: query.customer_id || null
};

// Construire l'URL avec les paramètres
let queryString = Object.entries(params)
  .filter(([key, value]) => value !== null)
  .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
  .join('&');

return {
  json: {
    query_string: queryString ? `?${queryString}` : '',
    params: params
  }
};

// Formater l'historique des commandes
const orders = $input.first().json || [];

const statusLabels = {
  'new': 'Nouvelle',
  'received': 'Reçue',
  'accepted': 'Acceptée',
  'in_preparation': 'En préparation',
  'awaiting_shipment': 'Prête',
  'awaiting_collection': 'À récupérer',
  'in_delivery': 'En livraison',
  'completed': 'Terminée',
  'rejected': 'Refusée',
  'cancelled': 'Annulée',
  'delivery_failed': 'Échec livraison'
};

const formattedOrders = (Array.isArray(orders) ? orders : [orders]).map(order => ({
  id: order.id,
  confirmation_code: order.confirmation_code || order.id?.slice(-6).toUpperCase(),
  status: order.status,
  status_label: statusLabels[order.status] || order.status,
  service_type: order.service_type,

  customer: {
    name: `${order.customer?.first_name || ''} ${order.customer?.last_name || ''}`.trim(),
    phone: order.customer?.phone || '',
    email: order.customer?.email || ''
  },

  items: order.items?.map(item => ({
    name: item.product_name,
    quantity: item.quantity,
    price: item.price ? parseInt(item.price) / 100 : 0,
    options: item.options?.map(opt => opt.name) || []
  })) || [],

  total: order.total ? parseInt(order.total) / 100 : 0,
  currency: 'EUR',

  timestamps: {
    created_at: order.created_at,
    expected_time: order.expected_time,
    confirmed_time: order.confirmed_time
  },

  source: order.custom_fields?.source || 'unknown'
}));

// Statistiques
const stats = {
  total_orders: formattedOrders.length,
  by_status: {},
  total_revenue: formattedOrders.reduce((sum, o) => sum + o.total, 0)
};

formattedOrders.forEach(order => {
  stats.by_status[order.status] = (stats.by_status[order.status] || 0) + 1;
});

return {
  json: {
    orders: formattedOrders,
    statistics: stats,
    retrieved_at: new Date().toISOString()
  }
};
